class SagaCoordinator:
    def __init__(self):
        self.steps = []  # List of dicts with keys: name, action, compensate
        self.execution_log = []  # Optional log of executed step names

    def add_step(self, name, action, compensate):
        # Defensive validation of step registration
        if not isinstance(name, str) or not name:
            raise ValueError("Step name must be a non-empty string")
        if not callable(action):
            raise ValueError("Action must be callable")
        if not callable(compensate):
            raise ValueError("Compensate must be callable")
        self.steps.append({"name": name, "action": action, "compensate": compensate})

    def execute(self, context):
        # Validate context – must be a dict (reject bool which is subclass of int)
        if type(context) is not dict:
            raise ValueError("Context must be a dict")

        results = {}
        completed_steps = []  # Keep track of successfully executed steps for compensation
        try:
            for step in self.steps:
                # Execute the action; any exception triggers compensation
                result = step["action"](context)
                results[step["name"]] = result
                completed_steps.append(step)
                self.execution_log.append(step["name"])  # Record successful execution
        except Exception as exc:
            # Compensation in reverse order of successful steps
            compensated = []
            for completed in reversed(completed_steps):
                try:
                    completed["compensate"](context)
                    compensated.append(completed["name"])
                except Exception:
                    # Compensation failures are logged but do not mask the original error
                    continue
            # Raise a domain-specific error with details
            raise SagaExecutionError(step["name"], exc, compensated) from exc

        return {"success": True, "results": results}

